import{_ as a,o as r,c as e,aj as o}from"./chunks/framework.Cn87zHeG.js";const d="/onerobot-H1/images/faq/power1.webp",l="/onerobot-H1/images/faq/power2.webp",i="/onerobot-H1/images/faq/power3.webp",m=JSON.parse('{"title":"开关机与安全","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"faq/power-safety.md","filePath":"faq/power-safety.md"}'),n={name:"faq/power-safety.md"};function s(h,t,p,q,c,b){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="开关机与安全" tabindex="-1">开关机与安全 <a class="header-anchor" href="#开关机与安全" aria-label="Permalink to &quot;开关机与安全&quot;">​</a></h1><p><a href="/onerobot-H1/downloads/faq/power-guide.pdf">下载《H1机器人电源开关说明》（PDF）</a></p><h2 id="q1" tabindex="-1">Q1. H1 怎么开机？ <a class="header-anchor" href="#q1" aria-label="Permalink to &quot;Q1. H1 怎么开机？ {#q1}&quot;">​</a></h2><p>机器人有三个电源开关，<strong>三者必须同时处于通电状态</strong>，机器人才会正常上电：</p><table tabindex="0"><thead><tr><th>开关</th><th>通电</th><th>断电</th></tr></thead><tbody><tr><td>应急开关（急停）</td><td>顺时针旋转弹起</td><td>直接按下（可隔着红胶套按）</td></tr><tr><td>机身普通开关</td><td>点按，按键凹入</td><td>点按，按键弹起</td></tr><tr><td>遥控开关</td><td>点按 ON</td><td>点按 OFF</td></tr></tbody></table><p>任意一个处于断电状态，机器人都不会通电。</p><p><img src="'+d+'" alt="应急开关（通电：顺时针旋转；断电：直接按下，可隔红胶套按）"></p><p><img src="'+l+'" alt="机身普通开关（通电：按键凹入；断电：按键弹起）"></p><p><img src="'+i+'" alt="遥控开关（通电：点按 ON；断电：点按 OFF）"></p><h2 id="q2" tabindex="-1">Q2. 怎么关机 / 断电？ <a class="header-anchor" href="#q2" aria-label="Permalink to &quot;Q2. 怎么关机 / 断电？ {#q2}&quot;">​</a></h2><p>按上表任一开关切到断电状态即可。<strong>紧急情况</strong>直接拍下应急开关（急停）最快。</p><h2 id="q3" tabindex="-1">Q3. 应急开关（急停）怎么用？什么时候用？ <a class="header-anchor" href="#q3" aria-label="Permalink to &quot;Q3. 应急开关（急停）怎么用？什么时候用？ {#q3}&quot;">​</a></h2><ul><li><strong>断电（急停）</strong>：直接拍下红色按钮，可隔着红胶套按。</li><li><strong>恢复供电</strong>：顺时针旋转让按钮弹起。</li><li><strong>使用时机</strong>：机器人出现失控、异常抖动、即将碰撞或任何危险情况时，第一时间拍下急停。当页面上的软件急停按钮点了无效时，立即按机器人本体的物理急停或直接断电。</li></ul><h2 id="q4" tabindex="-1">Q4. 机身指示灯不同颜色代表什么状态？ <a class="header-anchor" href="#q4" aria-label="Permalink to &quot;Q4. 机身指示灯不同颜色代表什么状态？ {#q4}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>灯效</th><th>含义</th></tr></thead><tbody><tr><td>白灯慢闪</td><td>未联网</td></tr><tr><td>白灯常亮</td><td>正常</td></tr><tr><td>红灯常亮</td><td>故障</td></tr><tr><td>红灯慢闪</td><td>低电</td></tr><tr><td>白灯呼吸</td><td>充电</td></tr></tbody></table><h2 id="q5" tabindex="-1">Q5. 操作机器人有哪些基本安全须知？ <a class="header-anchor" href="#q5" aria-label="Permalink to &quot;Q5. 操作机器人有哪些基本安全须知？ {#q5}&quot;">​</a></h2><ul><li>机械臂动作 / 跑机压测等运动测试前，机器人周围 <strong>2m × 2m 范围内必须无人、无障碍物</strong>。</li><li>运动过程中人员不要靠近，保持通道畅通。</li><li>急停按钮（软件）无效时，立即按本体物理急停或直接断电。</li><li><strong>固件升级（OTA）过程中严禁给机器人断电。</strong></li><li>手柄操作时禁止重复按同一个按键（详见<a href="./controller.html#q10">手柄使用注意事项</a>）。</li></ul>',17)])])}const _=a(n,[["render",s]]);export{m as __pageData,_ as default};
